//! Double-submit-cookie CSRF protection.

use std::sync::Arc;

use crate::auth::constant_time_eq;
use crate::{Middleware, Request, Response, ServerError, StatusCode};

/// The default CSRF cookie name.
pub const CSRF_COOKIE: &str = "rusty_csrf";
/// The default CSRF header name.
pub const CSRF_HEADER: &str = "x-csrf-token";

/// A CSRF token generated by the server.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CsrfToken(String);

impl CsrfToken {
    /// Generates a new 256-bit token rendered as lowercase hexadecimal.
    ///
    /// # Errors
    ///
    /// Returns [`ServerError::Random`] when the operating system random source
    /// is unavailable.
    pub fn generate() -> Result<Self, ServerError> {
        let mut bytes = [0_u8; 32];
        getrandom::getrandom(&mut bytes).map_err(|error| ServerError::Random(error.to_string()))?;
        let mut token = String::with_capacity(bytes.len() * 2);
        for byte in bytes {
            use std::fmt::Write;
            write!(&mut token, "{byte:02x}").expect("writing to a String cannot fail");
        }
        Ok(Self(token))
    }

    /// Returns the token as a string slice.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }

    /// Consumes the token and returns its string.
    #[must_use]
    pub fn into_string(self) -> String {
        self.0
    }
}

/// Configures double-submit-cookie CSRF protection.
///
/// Safe methods (`GET`, `HEAD`, `OPTIONS`) receive a token cookie when one is
/// missing. Unsafe methods must send the same token in both the cookie and the
/// configured header. The cookie is intentionally not `HttpOnly` so browser
/// clients can read it and mirror it into the header.
#[derive(Debug, Clone)]
pub struct CsrfMiddleware {
    cookie_name: String,
    header_name: String,
    path: String,
    secure: bool,
}

impl Default for CsrfMiddleware {
    fn default() -> Self {
        Self::new()
    }
}

impl CsrfMiddleware {
    /// Creates middleware with the default names (`rusty_csrf` and
    /// `x-csrf-token`).
    #[must_use]
    pub fn new() -> Self {
        Self {
            cookie_name: CSRF_COOKIE.to_owned(),
            header_name: CSRF_HEADER.to_owned(),
            path: "/".to_owned(),
            secure: false,
        }
    }

    /// Sets the cookie name.
    #[must_use]
    pub fn cookie_name(mut self, name: impl Into<String>) -> Self {
        self.cookie_name = name.into();
        self
    }

    /// Sets the header name.
    #[must_use]
    pub fn header_name(mut self, name: impl Into<String>) -> Self {
        self.header_name = name.into();
        self
    }

    /// Sets the cookie path.
    #[must_use]
    pub fn path(mut self, path: impl Into<String>) -> Self {
        self.path = path.into();
        self
    }

    /// Enables the `Secure` cookie attribute.
    ///
    /// Enable this whenever the application is served over HTTPS.
    #[must_use]
    pub fn secure(mut self, secure: bool) -> Self {
        self.secure = secure;
        self
    }

    /// Builds the middleware.
    ///
    /// # Errors
    ///
    /// Returns [`ServerError::Csrf`] when a cookie or header name is not a valid
    /// HTTP token.
    pub fn into_middleware(self) -> Result<Middleware, ServerError> {
        validate_name(&self.cookie_name, "cookie")?;
        validate_name(&self.header_name, "header")?;
        if self.path.is_empty() || self.path.contains([';', '\r', '\n']) {
            return Err(ServerError::Csrf(
                "the cookie path must be non-empty and cannot contain `;`".to_owned(),
            ));
        }

        let cookie_name = self.cookie_name;
        let header_name = self.header_name;
        let path = self.path;
        let secure = self.secure;
        Ok(Arc::new(move |context, next| {
            let request = context.request();
            let cookie_token = cookie_value(request, &cookie_name);

            if !request.method().is_safe() {
                let header_token = request.headers().get(&header_name);
                let valid = match (cookie_token.as_deref(), header_token) {
                    (Some(cookie), Some(header)) => {
                        constant_time_eq(cookie.as_bytes(), header.as_bytes())
                    }
                    _ => false,
                };
                if !valid {
                    return Ok(Response::text(
                        StatusCode::FORBIDDEN,
                        "CSRF token missing or invalid",
                    ));
                }
                if let Some(token) = cookie_token {
                    context.extensions_mut().insert(CsrfToken(token));
                }
                return next.run(context);
            }

            let issued_token = match cookie_token {
                Some(token) => {
                    context.extensions_mut().insert(CsrfToken(token));
                    None
                }
                None => {
                    let token = CsrfToken::generate()?;
                    context.extensions_mut().insert(token.clone());
                    Some(token.into_string())
                }
            };

            let mut response = next.run(context)?;
            if let Some(token) = issued_token {
                let mut cookie = format!("{cookie_name}={token}; Path={path}; SameSite=Lax");
                if secure {
                    cookie.push_str("; Secure");
                }
                response.headers_mut().append("set-cookie", cookie)?;
            }
            Ok(response)
        }))
    }
}

/// Creates CSRF middleware with the default configuration.
#[must_use]
pub fn csrf() -> Middleware {
    CsrfMiddleware::new()
        .into_middleware()
        .expect("default CSRF configuration is valid")
}

fn cookie_value(request: &Request, name: &str) -> Option<String> {
    request
        .headers()
        .get_all("cookie")
        .iter()
        .find_map(|header| {
            header.split(';').find_map(|pair| {
                let pair = pair.trim();
                let (key, value) = pair.split_once('=')?;
                (key == name).then(|| value.to_owned())
            })
        })
}

fn validate_name(name: &str, kind: &str) -> Result<(), ServerError> {
    if name.is_empty()
        || !name
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || b"!#$%&'*+-.^_`|~".contains(&byte))
    {
        return Err(ServerError::Csrf(format!(
            "the CSRF {kind} name must be a non-empty HTTP token"
        )));
    }
    Ok(())
}
